svg.script:
//!export-start
let _pb_running = false;
let _pn_speed = 0;
let _ps_label = 'FAN';
let _pc_on = '#22c55e';
let _pc_off = '#6b7280';
//!export-end

let fanAnimationFrame = null;
let fanAngle = 0;
let fanLastTime = null;

function toNumber(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function setText(el, text) {
  if (!el) return;
  while (el.firstChild) {
    el.removeChild(el.firstChild);
  }
  el.appendChild(document.createTextNode(text));
}

function postValue(id, value) {
  console.error('Not defined!', id, value);
}

function isRunning() {
  return !!_pb_running || toNumber(_pn_speed, 0) > 0;
}

function stopFanAnimation() {
  const blades = document.getElementById('fanBlades');
  if (fanAnimationFrame !== null) {
    cancelAnimationFrame(fanAnimationFrame);
    fanAnimationFrame = null;
  }
  fanLastTime = null;
  if (blades) {
    blades.setAttribute('transform', 'rotate(0 90 82)');
  }
}

function fanTick(timestamp) {
  const blades = document.getElementById('fanBlades');
  if (!blades || !isRunning()) {
    stopFanAnimation();
    return;
  }

  const speed = clamp(toNumber(_pn_speed, 0), 0, 100);
  const elapsed = fanLastTime === null ? 16 : timestamp - fanLastTime;
  fanLastTime = timestamp;
  fanAngle = (fanAngle + elapsed * (0.12 + speed * 0.015)) % 360;
  blades.setAttribute('transform', 'rotate(' + fanAngle + ' 90 82)');
  fanAnimationFrame = requestAnimationFrame(fanTick);
}

function startFanAnimation() {
  if (fanAnimationFrame === null) {
    fanLastTime = null;
    fanAnimationFrame = requestAnimationFrame(fanTick);
  }
}

function render() {
  const speed = clamp(toNumber(_pn_speed, 0), 0, 100);
  const running = isRunning();
  const blades = document.getElementById('fanBlades');
  const glow = document.getElementById('runGlow');
  const dot = document.getElementById('statusDot');
  const valueText = document.getElementById('valueText');
  const labelText = document.getElementById('labelText');

  if (blades) blades.setAttribute('opacity', running ? '1' : '0.55');
  if (running) {
    startFanAnimation();
  } else {
    stopFanAnimation();
  }
  if (glow) {
    glow.setAttribute('fill', _pc_on || '#22c55e');
    glow.setAttribute('opacity', running ? '0.45' : '0.12');
  }
  if (dot) dot.setAttribute('fill', running ? (_pc_on || '#22c55e') : (_pc_off || '#6b7280'));
  setText(valueText, running ? (speed > 0 ? Math.round(speed) + '%' : 'ON') : 'OFF');
  setText(labelText, _ps_label || '');
}

function putValue(id, value) {
  if (id === '_pb_running') {
    _pb_running = value === true || value === 1 || value === '1' || String(value).toLowerCase() === 'true';
  } else if (id === '_pn_speed') {
    _pn_speed = toNumber(value, _pn_speed);
  } else if (id === '_ps_label') {
    _ps_label = String(value ?? '');
  } else if (id === '_pc_on') {
    _pc_on = String(value ?? '#22c55e');
  } else if (id === '_pc_off') {
    _pc_off = String(value ?? '#6b7280');
  }
  render();
}

render();
